-- migration_v1_9_99.sql — Progetti PRJ e Analisi Gara & Dimensionamento (fase 2 di 6)
-- Schema cm_prj e cm_prj_* (38 tabelle), seed parametri globali, seed PRJ-2026-0001 (gara ASPI, non collegato),
-- permessi, versione. Idempotente: CREATE TABLE IF NOT EXISTS, INSERT IGNORE, ON DUPLICATE KEY UPDATE.
-- Le tabelle (v) sono versionate: valid_from, valid_to, version_no, is_current, ent_id (identita stabile).
-- I PRJ non vengono mai scritti in cm_projects. Collegamento opzionale via cm_prj.sp_project_id (ON DELETE SET NULL).

CREATE TABLE IF NOT EXISTS `pm_migration_sql` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `version` varchar(20) NOT NULL, `filename` varchar(190) NOT NULL,
  `applied_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`), UNIQUE KEY `uq_pm_migration_v_f` (`version`,`filename`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ════════════════════════════════════════════════════════════════════
-- 1. SCHEMA
-- ════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS `cm_prj` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_code` varchar(20) NOT NULL COMMENT 'PRJ-AAAA-NNNN, immutabile e non riutilizzabile',
  `nome` varchar(200) NOT NULL,
  `client_id` int(11) DEFAULT NULL,
  `client_raw` varchar(180) DEFAULT NULL,
  `exec_company_id` int(11) DEFAULT NULL,
  `project_type` enum('Gara Consip/MePA/Carrier','Progetto Standard','Trattativa Diretta') DEFAULT NULL,
  `stato` enum('Bozza','In analisi','Offerta presentata','Aggiudicato','Perso','Ritirato','In esecuzione','Chiuso') NOT NULL DEFAULT 'Bozza',
  `responsabile_user_id` int(11) DEFAULT NULL,
  `sp_project_id` int(11) DEFAULT NULL COMMENT 'Commessa SP collegata (cm_projects.id), opzionale',
  `sp_linked_at` datetime DEFAULT NULL,
  `codice_gara` varchar(60) DEFAULT NULL,
  `cig` varchar(20) DEFAULT NULL,
  `stazione_appaltante` varchar(200) DEFAULT NULL,
  `data_offerta` date DEFAULT NULL,
  `data_aggiudicazione` date DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `scenario_riferimento_id` int(11) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prj_code` (`prj_code`),
  KEY `idx_prj_sp` (`sp_project_id`),
  KEY `idx_prj_client` (`client_id`),
  KEY `idx_prj_company` (`exec_company_id`),
  KEY `idx_prj_stato` (`stato`),
  CONSTRAINT `ck_prj_code` CHECK (`prj_code` REGEXP '^PRJ-[0-9]{4}-[0-9]{4}$'),
  CONSTRAINT `fk_prj_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_prj_company` FOREIGN KEY (`exec_company_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_prj_sp` FOREIGN KEY (`sp_project_id`) REFERENCES `cm_projects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_prj_resp` FOREIGN KEY (`responsabile_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_prj_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Progetti PRJ (gare e iniziative da dimensionare), distinti dalle commesse SP';

CREATE TABLE IF NOT EXISTS `cm_prj_sequence` (
  `year` smallint(6) NOT NULL,
  `last_no` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Progressivo annuale del codice PRJ (SELECT FOR UPDATE)';

CREATE TABLE IF NOT EXISTS `cm_prj_link_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `sp_project_id` int(11) DEFAULT NULL COMMENT 'Nessuna FK: lo storico sopravvive alla cancellazione della commessa',
  `sp_project_code` varchar(40) DEFAULT NULL,
  `azione` enum('collegato','scollegato','sostituito','orfano_da_sync') NOT NULL,
  `motivo` varchar(255) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_plh_prj` (`prj_id`,`created_at`),
  KEY `idx_plh_sp` (`sp_project_id`),
  CONSTRAINT `fk_plink_history_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Storico collegamenti PRJ - commessa SP';

CREATE TABLE IF NOT EXISTS `cm_prj_source` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) DEFAULT NULL COMMENT 'NULL = fonte globale',
  `prj_key` int(11) AS (COALESCE(`prj_id`,0)) PERSISTENT,
  `tipo` enum('documento_gara','mercato','stima_interna') NOT NULL,
  `codice` varchar(40) NOT NULL,
  `titolo` varchar(255) NOT NULL,
  `url` varchar(500) DEFAULT NULL,
  `data_riferimento` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_psrc` (`prj_key`,`codice`),
  CONSTRAINT `fk_psource_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fonti dei dati (documenti di gara, mercato, stime)';

CREATE TABLE IF NOT EXISTS `cm_prj_gara` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `durata_mesi` int(11) DEFAULT NULL,
  `mesi_operativi` int(11) DEFAULT NULL,
  `phase_in_giorni` int(11) DEFAULT NULL,
  `phase_in_retribuito` tinyint(1) NOT NULL DEFAULT 0,
  `handover_giorni` int(11) DEFAULT NULL,
  `rinnovo_mesi` int(11) DEFAULT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pgara` (`prj_id`,`version_no`),
  KEY `idx_pgara_ent` (`ent_id`,`is_current`),
  KEY `idx_pgara_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_pgara_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Dati di gara (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_presales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `cost_center` enum('Ufficio Gare','Sicurezza','Ingegneria/Analisi Tecnica','Project Management') NOT NULL,
  `hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `hourly_rate` decimal(8,2) DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ppres` (`prj_id`,`cost_center`),
  CONSTRAINT `fk_ppresales_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Effort presales del PRJ (struttura di cm_presales_effort)';

CREATE TABLE IF NOT EXISTS `cm_prj_tender_base` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `year` smallint(6) NOT NULL,
  `canone_eur` decimal(14,2) NOT NULL DEFAULT 0.00,
  `uncommitted_eur` decimal(14,2) NOT NULL DEFAULT 0.00,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ptb` (`prj_id`,`year`,`version_no`),
  KEY `idx_ptender_base_ent` (`ent_id`,`is_current`),
  KEY `idx_ptender_base_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_ptender_base_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Base d asta per anno (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_rate_card` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `profilo` varchar(120) NOT NULL,
  `eur_giorno` decimal(10,2) NOT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prc` (`prj_id`,`profilo`,`version_no`),
  KEY `idx_prate_card_ent` (`ent_id`,`is_current`),
  KEY `idx_prate_card_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_prate_card_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tariffario Uncommitted (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_area` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `codice` varchar(10) NOT NULL,
  `nome` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_parea` (`prj_id`,`codice`),
  CONSTRAINT `fk_parea_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Aree di servizio';

CREATE TABLE IF NOT EXISTS `cm_prj_service` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `area_id` int(11) DEFAULT NULL,
  `codice` varchar(20) NOT NULL,
  `nome` varchar(200) NOT NULL,
  `modalita` enum('remoto','ibrido','in_sede') NOT NULL DEFAULT 'remoto',
  `max_interventi_sede_anno` int(11) DEFAULT NULL,
  `fuori_orario_remoto` int(11) DEFAULT NULL,
  `fuori_orario_sede` int(11) DEFAULT NULL,
  `fuori_orario_note` varchar(255) DEFAULT NULL,
  `h24` tinyint(1) NOT NULL DEFAULT 0,
  `h24_note` varchar(255) DEFAULT NULL,
  `avvio_anno` tinyint(4) NOT NULL DEFAULT 1,
  `avvio_note` varchar(120) DEFAULT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_psvc` (`prj_id`,`codice`,`version_no`),
  KEY `idx_psvc_area` (`area_id`),
  KEY `idx_pservice_ent` (`ent_id`,`is_current`),
  KEY `idx_pservice_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_pservice_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_psvc_area` FOREIGN KEY (`area_id`) REFERENCES `cm_prj_area` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Servizi (v), referenziati per ent_id';

CREATE TABLE IF NOT EXISTS `cm_prj_service_technology` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `service_id` int(11) NOT NULL COMMENT 'cm_prj_service.ent_id',
  `technology_id` int(11) DEFAULT NULL,
  `technology_raw` varchar(200) NOT NULL,
  `versioni` varchar(120) DEFAULT NULL,
  `h24` tinyint(1) NOT NULL DEFAULT 0,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pstech` (`prj_id`,`service_id`,`technology_raw`),
  KEY `idx_pstech_tech` (`technology_id`),
  CONSTRAINT `fk_pservice_technology_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pstech_tech` FOREIGN KEY (`technology_id`) REFERENCES `technologies` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tecnologie per servizio';

CREATE TABLE IF NOT EXISTS `cm_prj_asset_metric` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `service_id` int(11) DEFAULT NULL,
  `metrica` varchar(120) NOT NULL,
  `valore` decimal(18,2) NOT NULL,
  `unita` varchar(20) DEFAULT NULL,
  `year` smallint(6) NOT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_passet` (`prj_id`,`metrica`,`year`,`version_no`),
  KEY `idx_passet_metric_ent` (`ent_id`,`is_current`),
  KEY `idx_passet_metric_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_passet_metric_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metriche asset per anno (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_ticket_group` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `area` varchar(10) DEFAULT NULL,
  `nome` varchar(120) NOT NULL,
  `ordine` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ptg` (`prj_id`,`nome`),
  CONSTRAINT `fk_pticket_group_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Gruppi di risoluzione ticket';

CREATE TABLE IF NOT EXISTS `cm_prj_ticket_mapping` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `group_id` int(11) NOT NULL,
  `service_id` int(11) NOT NULL COMMENT 'cm_prj_service.ent_id',
  `quota` decimal(6,4) NOT NULL DEFAULT 1.0000,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ptm` (`group_id`,`service_id`,`version_no`),
  KEY `idx_pticket_mapping_ent` (`ent_id`,`is_current`),
  KEY `idx_pticket_mapping_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_pticket_mapping_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ptm_group` FOREIGN KEY (`group_id`) REFERENCES `cm_prj_ticket_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Mapping gruppo -> servizio con quota (v), stima interna';

CREATE TABLE IF NOT EXISTS `cm_prj_ticket_volume` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `group_id` int(11) NOT NULL,
  `year` smallint(6) NOT NULL,
  `tipo` enum('CTASK','INC','SCTASK') NOT NULL,
  `quantita` int(11) NOT NULL DEFAULT 0,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ptv` (`group_id`,`year`,`tipo`,`version_no`),
  KEY `idx_pticket_volume_ent` (`ent_id`,`is_current`),
  KEY `idx_pticket_volume_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_pticket_volume_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ptv_group` FOREIGN KEY (`group_id`) REFERENCES `cm_prj_ticket_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Volumi ticket per gruppo, anno e tipo (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_aht` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `tipo` enum('CTASK','INC','SCTASK') NOT NULL,
  `service_id` int(11) NOT NULL DEFAULT 0 COMMENT '0 = tutti i servizi, altrimenti cm_prj_service.ent_id',
  `ore` decimal(8,2) NOT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_paht` (`prj_id`,`tipo`,`service_id`,`version_no`),
  KEY `idx_paht_ent` (`ent_id`,`is_current`),
  KEY `idx_paht_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_paht_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ore medie per ticket (v), per tipo e opzionalmente per servizio';

CREATE TABLE IF NOT EXISTS `cm_prj_productivity` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `ore_utili_fte` decimal(8,2) NOT NULL DEFAULT 1600.00,
