  `ent_id` int(11) DEFAULT NULL COMMENT 'Identita stabile del record logico (id della prima versione)',
  `valid_from` date NOT NULL DEFAULT '2026-01-01',
  `valid_to` date DEFAULT NULL,
  `version_no` int(11) NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `change_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pprod` (`prj_id`,`version_no`),
  KEY `idx_pproductivity_ent` (`ent_id`,`is_current`),
  KEY `idx_pproductivity_asof` (`valid_from`,`valid_to`),
  CONSTRAINT `fk_pproductivity_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Produttivita e banda volumi (v)';

CREATE TABLE IF NOT EXISTS `cm_prj_profile` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `codice` varchar(20) NOT NULL,
  `nome` varchar(200) NOT NULL,
  `seniority` varchar(30) DEFAULT NULL,
  `tipo` enum('obbligatorio','supporto','governance') NOT NULL,
  `h24` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Il profilo svolge H24 (indennita)',
  `nearshore_ammesso` tinyint(1) NOT NULL DEFAULT 0,
  `ordine` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pprof` (`prj_id`,`codice`),
  CONSTRAINT `fk_pprofile_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Profili richiesti';

CREATE TABLE IF NOT EXISTS `cm_prj_profile_req` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `profile_id` int(11) NOT NULL,
  `anni_min` int(11) DEFAULT NULL,
  `titolo_min` varchar(120) DEFAULT NULL,
  `lingue` varchar(120) DEFAULT NULL,
  `responsabilita` text DEFAULT NULL,
  `source_id` int(11) DEFAULT NULL,
  `source_ref` varchar(120) DEFAULT NULL,
