  `sp_project_id` int(11) DEFAULT NULL COMMENT 'Commessa SP collegata al momento del calcolo (nessuna FK)',
  `as_of` date NOT NULL,
  `params_hash` char(64) NOT NULL,
  `input_json` longtext NOT NULL,
  `app_version` varchar(20) NOT NULL,
  `schema_version` varchar(20) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_prun_prj` (`prj_id`,`created_at`),
  KEY `idx_prun_scen` (`scenario_id`),
  KEY `idx_prun_sp` (`sp_project_id`),
  KEY `idx_prun_hash` (`params_hash`),
  CONSTRAINT `fk_prun_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Calc run immutabili';

CREATE TABLE IF NOT EXISTS `cm_prj_calc_result` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `run_id` int(11) NOT NULL,
  `ambito` enum('totale','servizio','profilo','anno','zona') NOT NULL,
  `ambito_ref` varchar(60) NOT NULL DEFAULT '',
  `metrica` varchar(60) NOT NULL,
  `valore` decimal(18,4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pres` (`run_id`,`ambito`,`ambito_ref`,`metrica`),
  CONSTRAINT `fk_pres_run` FOREIGN KEY (`run_id`) REFERENCES `cm_prj_calc_run` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Risultati dei calc run';

CREATE TABLE IF NOT EXISTS `cm_prj_actual` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prj_id` int(11) NOT NULL,
  `year` smallint(6) NOT NULL,
  `month` tinyint(4) NOT NULL,
  `service_id` int(11) NOT NULL DEFAULT 0,
  `metrica` varchar(60) NOT NULL,
  `valore` decimal(18,4) DEFAULT NULL,
  `origine` enum('dgb','timesheet','report','manuale') NOT NULL,
  `computed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pact` (`prj_id`,`year`,`month`,`service_id`,`metrica`,`origine`),
  CONSTRAINT `fk_pactual_prj` FOREIGN KEY (`prj_id`) REFERENCES `cm_prj` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Consuntivi mensili per il confronto stimato/consuntivo';

